// SCE Mesh for Kotlin hosts — the Kotlin twin of backends/rust/mesh
// (`sce-rust-mesh`): the standard Mesh documents generated from
// `sce:std/mesh` (src/commonMain/kotlin/generated/, committed, regenerated by
// generate.sh and held to its sources by sce-build's drift test), and the
// router core that applies them. Transport-free: bytes and the clock come
// from the host (SCE_MESH.md §mesh-6.4).

plugins {
    alias(libs.plugins.kotlin.multiplatform)
    `maven-publish`
}

group = "com.sce"
version = "1.0.0"

kotlin {
    jvmToolchain(17)
    jvm()
    compilerOptions {
        allWarningsAsErrors.set(true)
    }

    sourceSets {
        val commonMain by getting {
            dependencies {
                // The generated rules and codec call into the forge runtime;
                // the router core meets the engine through the runtime's
                // host-processor surface.
                implementation(project(":sce-forge-runtime-kotlin"))
                implementation(project(":sce-kotlin-runtime"))
            }
        }
        val commonTest by getting {
            dependencies {
                implementation(kotlin("test"))
            }
        }
    }
}
